import { AttachedPageInternal } from '@common/api/pages/shapes';

import { markUnsavedPagesAsSaved } from '@client-platform/api/workspaces';

import { getCurrentSync } from '@client-platform/api';
import { Workspace, WorkspacePlatformModule } from '@client-platform/shapes';

const markUnsavedPagesAsSavedInWorkspaceSnapshot = (workspace: Workspace): Workspace => ({
    ...workspace,
    snapshot: {
        ...workspace.snapshot,
        windows: workspace.snapshot.windows.map((window) => ({
            ...window,
            workspacePlatform: {
                ...window.workspacePlatform,
                pages: window.workspacePlatform?.pages?.map((page: AttachedPageInternal) => ({
                    ...page,
                    hasUnsavedChanges: false
                }))
            }
        }))
    }
});

export const saveWorkspaceInternal = async (workspace: Workspace, p?: WorkspacePlatformModule): Promise<void> => {
    const platform = p ?? getCurrentSync();
    await platform.Storage.saveWorkspace(markUnsavedPagesAsSavedInWorkspaceSnapshot(workspace));
    await markUnsavedPagesAsSaved();
};

export const createWorkspaceInternal = async (workspace: Workspace, p?: WorkspacePlatformModule): Promise<void> => {
    const platform = p ?? getCurrentSync();
    await platform.Storage.createWorkspace({ workspace: markUnsavedPagesAsSavedInWorkspaceSnapshot(workspace) });
    await markUnsavedPagesAsSaved();
};

export const updateWorkspaceInternal = async (workspace: Workspace, p?: WorkspacePlatformModule): Promise<void> => {
    const platform = p ?? getCurrentSync();
    await platform.Storage.updateWorkspace({
        workspaceId: workspace.workspaceId,
        workspace: markUnsavedPagesAsSavedInWorkspaceSnapshot(workspace)
    });
    await markUnsavedPagesAsSaved();
};
